package com.primehr.rewardsrecognition.domain;
import com.primehr.rsp.domain.RspAuditedEntity;import jakarta.persistence.*;import java.math.BigDecimal;import java.time.Instant;
@Entity @Table(name="rr_incentive_authorization") public class RrIncentiveAuthorization extends RspAuditedEntity{
 public enum Type{MONETARY,NON_MONETARY}@Column(name="award_record_id",nullable=false,length=36)private String awardRecordId;@Enumerated(EnumType.STRING)@Column(name="incentive_type",nullable=false,length=20)private Type incentiveType;@Column(nullable=false,length=1000)private String description;@Column(name="authorized_amount",precision=19,scale=2)private BigDecimal authorizedAmount;@Column(name="currency_code",length=3)private String currencyCode;@Column(name="authorization_reference",nullable=false,length=200)private String authorizationReference;@Column(name="authorized_by",nullable=false,length=100)private String authorizedBy;@Column(name="authorized_at",nullable=false)private Instant authorizedAt;protected RrIncentiveAuthorization(){}public RrIncentiveAuthorization(String a,String award,Type type,String description,BigDecimal amount,String currency,String reference,String actor,Instant at){super(a);awardRecordId=requiredText(award,"awardRecordId");incentiveType=java.util.Objects.requireNonNull(type,"incentiveType");this.description=requiredText(description,"description");authorizationReference=requiredText(reference,"authorizationReference");authorizedBy=requiredText(actor,"actor");authorizedAt=java.util.Objects.requireNonNull(at,"authorizedAt");if(type==Type.MONETARY){if(amount==null||amount.signum()<=0)throw new IllegalArgumentException("Monetary incentive amount must be positive");authorizedAmount=amount.setScale(2,java.math.RoundingMode.HALF_UP);currencyCode=requiredText(currency,"currencyCode").toUpperCase(java.util.Locale.ROOT);if(currencyCode.length()!=3)throw new IllegalArgumentException("currencyCode must contain three letters");}else if(amount!=null||currency!=null&&!currency.isBlank())throw new IllegalArgumentException("Non-monetary incentive cannot contain an amount or currency");}public String getAwardRecordId(){return awardRecordId;}public Type getIncentiveType(){return incentiveType;}public String getDescription(){return description;}public BigDecimal getAuthorizedAmount(){return authorizedAmount;}public String getCurrencyCode(){return currencyCode;}public String getAuthorizationReference(){return authorizationReference;}public String getAuthorizedBy(){return authorizedBy;}public Instant getAuthorizedAt(){return authorizedAt;}}
